crops = {
    'lower_premolar_R': (int(W*0.28), int(H*0.45), int(W*0.45), int(H*0.75)),
    'lower_premolar_L': (int(W*0.55), int(H*0.45), int(W*0.72), int(H*0.75)),
}

for name, box in crops.items():
    crop = im.crop(box)
    crop.save(f'crops/{name}.jpg')
